/* Explicitly selected local examples; no production writes or clinical prescriptions. */
(function(){
const proposedSettings=[['seller_hold_days','Seller holding period',15,'days'],['travel_days','Planned travel duration',3,'days'],['warmup_days','Warm-up duration',10,'days'],['travel_check_hours','Travel check interval',3,'hours']];
function addSettings(){ensureTypedConfig();for(const [key,name,value,unit] of proposedSettings)if(!state.items.some(i=>i.configKey===key))state.items.push({id:'example-'+key,name,module:'Common',categoryId:'category-shared-configuration',subcategoryId:'subcategory-shared-settings',purpose:'Procurement example — choose the applicable period for each load',description:'User-supplied example, not a verified live default.',unit,active:true,shares:['Procurement','Feed'],revision:1,itemKind:'config_value',configKey:key,valueType:'integer',value,currency:'',scope:'Per-load example; no live scheduling',sourceKind:'proposed_config',sourceOwner:'Procurement'});}
function simple(title,steps){const nodes=[{id:'start',type:'start',label:'Start '+title,x:260,y:20,next:'step-0'}];steps.forEach((s,i)=>nodes.push({id:'step-'+i,type:'action',action:'Instruction',label:s,next:i+1<steps.length?'step-'+(i+1):'end',x:260,y:150+i*160}));nodes.push({id:'end',type:'end',label:'Finish '+title,x:260,y:150+steps.length*160});return {title,version:0,published:null,nodes,exampleOnly:true};}
function retain(module,s){state.archivedSops??={};state.archivedSops[module]??=[];compositionEnsureWorkflowId(s);state.archivedSops[module].push(s);return s.workflowId;}
window.openBusinessExamples=function(){modal('Examples to review',`<p>These are examples of what the shared builder can express. Your department can create its own instructions and combine any existing SOPs.</p><section class="card"><h3>Procurement · from seller inspection to warm-up</h3><p>Reuse the current inspection form, then join selection, holding, transport and warm-up. Show approvals, changing animal groups and work that happens alongside transit.</p><button class="primary" onclick="installProcurementExample()" ${canEdit()?'':'disabled'}>Open Procurement example</button></section><section class="card"><h3>Health · assessment and treatment</h3><p>Keep the existing symptom assessment and approved disease / age-band protocols. Use the selected protocol in work instructions; preserve review, evidence and treatment versions.</p><button onclick="closeModal();go('Health','SOPs')">Open Health instructions</button><button onclick="closeModal();productionNavigate('Health','Health Config')">View existing Health settings</button></section><section class="card"><h3>Sales · eligibility and shared values</h3><p>Species, breed and sex-specific choices, minimum weight, tolerance and prices belong to Sales settings. Weighing can read the approved settings. Reporting thresholds and actual sale prices remain separate.</p><button onclick="closeModal();productionNavigate('Sales','Sales Config')">Open Sales settings</button></section><p class="muted">Examples are local drafts. No operators receive work and no farm records change.</p>`,true);};
window.installProcurementExample=function(){if(!canEdit())return;addSettings();state.exampleProcurement??={};let existing=compositionWorkflows().find(e=>e.workflow.exampleKey==='procurement-master-v1');if(existing){if(existing.module==='Procurement'&&state.sops.Procurement!==existing.workflow){const index=state.archivedSops.Procurement.indexOf(existing.workflow);current='Procurement';switchSop(index);}closeModal();go('Procurement','Editor');return;}
const inspection=buildProcurementQuestionnaire(CURRENT_PROCUREMENT_SOURCE);inspection.title='Seller inspection · current published questions';inspection.exampleOnly=true;inspection.sourceProvenance=CURRENT_PROCUREMENT_SOURCE.provenance;
const children=[inspection,
 simple('Tagging, vaccination and seller holding',['Use only the approved candidate list; reconcile each candidate with its tag before creating herd identity.','Follow the selected published vaccination plan. Keep prior-dose, age, purpose, spacing and clinical deferral rules.','Record vaccination evidence and holding start. Wait the configured holding period before release.']),
 simple('Pre-departure review and loading',['Reinspect the previously approved animals using the selected inspection questions. Keep each earlier decision and the new review.','Approve the final boarding list. Rejected or held animals cannot enter the truck; reconcile identities, not just totals.','Sanitize the truck and capture the required evidence.','Calculate familiar feed for travel plus warm-up using the applicable ration, selected animals and units. Confirm the quantity packed.']),
 simple('Transit checks',['Record departure of the final approved boarding group.','At each configured travel interval, check the animals and capture the required photos/videos. Record exceptions for review.','Reconcile the received animals against the boarding list; record shortages and obtain the required review.']),
 simple('Destination shed preparation',['Begin only after transit has started for this load.','Empty the allocated sheds and sanitize them.','Prepare water and ORS as instructed; record evidence and confirm readiness before arrival.']),
 simple('Warm-up and feed transition',['Confirm arrival and use the received animal group.','Use the approved transition plan to combine the carried familiar feed with farm or experimental feed. No mixing ratio is invented by this example.','Record daily checks and feed adjustments for the configured warm-up period. Obtain release approval.'])];
const ids=children.map(s=>retain('Procurement',s));const labels=['Seller inspection and selection','Tag, vaccinate and hold','Reinspect and prepare transport','Transit','Prepare destination sheds','Warm-up'];
const stages=ids.map((id,i)=>({id:'stage-'+i,label:labels[i],childWorkflowId:id,dependencies:i?[{stageId:'stage-'+(i-1),state:'completed'}]:[],approvalRequired:[0,2,5].includes(i),approvalRole:'CEO / CXO',waitDays:0,waitDaysRef:i===1?'seller_hold_days':i===3?'travel_days':i===5?'warmup_days':'',repeatCheckHours:0,repeatCheckHoursRef:i===3?'travel_check_hours':''}));
stages[1].dependencies=[{stageId:'stage-0',state:'approved'}];stages[3].dependencies=[{stageId:'stage-2',state:'approved'}];stages[4].dependencies=[{stageId:'stage-3',state:'started'}];stages[5].dependencies=[{stageId:'stage-3',state:'completed'},{stageId:'stage-4',state:'completed'}];
const parent=simple('Procurement · purchase, transit and warm-up',['Follow the stages and approval checks in this plan.']);parent.stagePlan={stages};parent.exampleKey='procurement-master-v1';parent.exampleNotes='User-supplied example. 100 offered / 70 selected are sample figures; actual candidate identity and decisions remain in the production review feature. Holding 15 days, travel 3 days, warm-up 10 days and 3-hour checks are editable local examples.';parent.exampleSettings=proposedSettings.map(([key])=>key);
if(state.sops.Procurement)retain('Procurement',state.sops.Procurement);state.sops.Procurement=parent;compositionEnsureWorkflowId(parent);persist();closeModal();go('Procurement','Editor');toast('Example draft created. Existing instructions were kept. Review Stages and approvals.');};
const previousEditor=renderEditor;renderEditor=function(){previousEditor();const s=sop();if(s.exampleKey==='procurement-master-v1'&&!s.stagePlan?.stages.length){const toolbar=$('.toolbar');toolbar?.insertAdjacentHTML('beforeend','<button onclick="procurementExampleContext()">Animal groups & settings</button>');}};
window.procurementExampleContext=function(){const s=sop();modal('Procurement example · animal groups and settings',`<p>${esc(s.exampleNotes||'')}</p><div class="flowmini"><b>100 offered</b>→<b>70 selected</b>→<b>Boarding subset</b>→<b>Received subset</b></div><p>Each group must retain individual identities and decision history. Approval of 70 animals does not automatically approve those same 70 for transport.</p><div class="tablewrap"><table><thead><tr><th>Stage</th><th>What changes</th><th>Existing or proposed</th></tr></thead><tbody><tr><td>Seller inspection</td><td>7 load fields + 40 questions per animal; field recommendation and reviewer decision are separate</td><td>Existing published form, imported as a local draft</td></tr><tr><td>Tagging / holding</td><td>Accepted candidate → tagged animal, vaccination and holding start</td><td>Existing domain primitives; connected handoff needs implementation</td></tr><tr><td>Boarding</td><td>Repeat review; remove rejected / held animals from the selected set</td><td>Proposed connected review stage</td></tr><tr><td>Arrival / warm-up</td><td>Reconcile received set; use its feed plan and evidence</td><td>Existing domain primitives; composed execution proposed</td></tr></tbody></table></div><h3>Durations and repeated checks</h3><p>Change the corresponding stage’s waiting period or travel check interval in Stages and approvals. These are per-plan examples, not a live farm schedule.</p><p><b>Feed to pack:</b> selected animals × daily familiar-feed ration × (travel days + warm-up days), calculated separately for each feed/ration group. Actual ration, unit conversion, wastage and blend rules remain owned by Feed.</p><h3>Vaccination stays with its published plan</h3><p>Reference the approved plan and its clinical checks. Creating an inventory vaccine does not set its dose or schedule. The example does not prescribe any treatment.</p><a href="https://dashboard.mesha.sg/vaccination/plan" target="_blank" rel="noopener">Open existing vaccination plan ↗</a><details><summary>Evidence and unresolved integration</summary><p>Staging published vaccine plan v9; v10 is a draft. Procurement holding/transit schemas exist but observed tables were empty. Candidate-to-herd promotion and the complete joined execution were not established as implemented.</p></details>`,true);};
})();
